import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';

describe('ToolRegistry', () => {
  it('throws at register time naming the tool when a static inputSchema cannot be compiled ([validated by: A static ToolDefinition has its inputSchema compiled once at register time, so a schema that is not valid JSON Schema throws synchronously from register with an error message naming the offending tool](../../specs/hal-engine-tool-input-validation/spec.md#L26))', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_tool/);
  });

  it('validates input against the resolved definition schema before calling the executor ([validated by: When input omits a property listed in required, ToolRegistry.execute returns a ToolResponse whose result names the missing property as required and never invokes the executor](../../specs/hal-engine-tool-input-validation/spec.md#L14))', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'test_tool',
        description: 'A test tool',
        inputSchema: {
          type: 'object',
          properties: {requiredField: {type: 'string'}},
          required: ['requiredField'],
        },
      },
      async () => {
        calls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('test_tool', {});

    expect({
      calls,
      result: response.result,
    }).toEqual({
      calls: 0,
      result: expect.stringMatching(/requiredField.*required/i),
    });
  });

  it('passes valid input with unlisted extra properties through to the executor unchanged ([validated by: When input satisfies required, declared property types and enum, ToolRegistry.execute invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting additionalProperties: false, coercing types or applying defaults.](../../specs/hal-engine-tool-input-validation/spec.md#L16))', async () => {
    const registry = new ToolRegistry();
    let capturedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'extra_tool',
        description: 'd',
        inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    await registry.execute('extra_tool', {a: 'val', extra: 123});

    expect(capturedInput).toEqual({a: 'val', extra: 123});
  });

  it('throws Unknown tool error for unregistered tool name ([validated by: When ToolRegistry.execute is called with a tool name that has not been registered, it throws Unknown tool: <name> because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.](../../specs/hal-engine-tool-input-validation/spec.md#L17))', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('unknown', {})).rejects.toThrow(/Unknown tool: unknown/);
  });

  it('compiles a static tool schema once and reuses it across multiple calls ([validated by: A static tool\'s inputSchema is compiled at register time and reused on every execute call without re-reading or re-compiling definition.inputSchema.](../../specs/hal-engine-tool-input-validation/spec.md#L27))', async () => {
    const registry = new ToolRegistry();
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');

    registry.register(
      {
        name: 'static_tool',
        description: 'd',
        inputSchema: {type: 'object', properties: {p: {type: 'string'}}},
      },
      async () => 'ok'
    );

    const initialCompileCount = compileSpy.mock.calls.length;

    await registry.execute('static_tool', {p: 'a'});
    await registry.execute('static_tool', {p: 'b'});

    expect(compileSpy.mock.calls.length).toBe(initialCompileCount);
    compileSpy.mockRestore();
  });

  it('caches dynamic validators by schema object reference in a WeakMap ([validated by: A function-valued ToolDefinitionSource resolves its definition on each execute call and validates against the inputSchema returned for that call, caching compiled validators by schema object reference (WeakMap) so distinct returned schemas each enforce their own rules.](../../specs/hal-engine-tool-input-validation/spec.md#L28))', async () => {
    const registry = new ToolRegistry();
    const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
    const schema = {type: 'object', properties: {p: {type: 'string'}}};

    registry.register(
      () => ({
        name: 'dynamic_tool',
        description: 'd',
        inputSchema: schema,
      }),
      async () => 'ok'
    );

    await registry.execute('dynamic_tool', {p: 'a'});
    await registry.execute('dynamic_tool', {p: 'b'});

    expect(compileSpy.mock.calls.length).toBe(1);
    compileSpy.mockRestore();
  });
});

